import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { computeOutcomeScore, OUTCOME_WEIGHTS, type OutcomeInputs } from './outcome.js';

// The oracle: contracts/score-vectors.json, generated by
// contracts/outcome_score_reference.py. Every vector must match exactly.
const here = path.dirname(fileURLToPath(import.meta.url));
const vectorsPath = path.resolve(here, '../../../../contracts/score-vectors.json');
const contract = JSON.parse(fs.readFileSync(vectorsPath, 'utf8')) as {
  weights: Record<string, number>;
  vectors: Array<{
    name: string;
    input: OutcomeInputs;
    expected: {
      score: number | null;
      kept: boolean;
      components: Record<string, number | null>;
    };
  }>;
};

describe('computeOutcomeScore — contract vectors', () => {
  it('uses the contract weights', () => {
    expect(OUTCOME_WEIGHTS).toEqual(contract.weights);
  });

  it('has vectors to check', () => {
    expect(contract.vectors.length).toBeGreaterThanOrEqual(14);
  });

  for (const v of contract.vectors) {
    it(v.name, () => {
      expect(computeOutcomeScore(v.input)).toEqual(v.expected);
    });
  }
});

describe('computeOutcomeScore — audit counter-examples (Bet 5)', () => {
  const base: OutcomeInputs = {
    plan: 'train',
    setsDone: 15,
    setsPlanned: 15,
    protein: 160,
    proteinTarget: 160,
    calories: 2500,
    calorieTarget: 2500,
    bwSlope: -0.4,
    goalRate: -0.4,
  };

  it('skipped session + 50% protein scores below 60', () => {
    const r = computeOutcomeScore(Object.assign({}, base, { setsDone: 0, protein: 80 }));
    expect(r.score).not.toBeNull();
    expect(r.score!).toBeLessThan(60);
    expect(r.kept).toBe(false);
  });

  it('a perfect planned rest day scores 100', () => {
    const r = computeOutcomeScore(Object.assign({}, base, { plan: 'rest', setsDone: 0 }));
    expect(r.score).toBe(100);
  });

  it('missing targets make Pr/Ca unknown, so the day is unscored', () => {
    const r = computeOutcomeScore(
      Object.assign({}, base, { proteinTarget: null, calorieTarget: null })
    );
    expect(r.score).toBeNull();
    expect(r.kept).toBe(false);
  });
});
